"""System: PL-03 -> PL-02 -> PL-01 on a real CSV, with the real `mdata.load_prices` (no fakes)."""

from __future__ import annotations

import json
import math
from pathlib import Path

import pytest

import risk
from mdata import GapError, Prices, load_prices


def write_csv(path: Path, payload: dict) -> Path:
    """The `mdata.Prices` sample as a long `date,ticker,close` CSV."""
    lines = ["date,ticker,close"]
    for i, day in enumerate(payload["dates"]):
        lines += [f"{day},{ticker},{payload['closes'][ticker][i]}" for ticker in payload["tickers"]]
    path.write_text("\n".join(lines) + "\n")
    return path


@pytest.fixture
def sample(contract_sample) -> dict:
    return contract_sample("mdata.Prices")


@pytest.fixture
def csv_path(tmp_path, sample) -> Path:
    return write_csv(tmp_path / "prices.csv", sample)


def test_real_load_prices_builds_the_prices_sample(csv_path, sample):
    expected = Prices(
        dates=tuple(sample["dates"]),
        tickers=tuple(sample["tickers"]),
        closes={ticker: tuple(series) for ticker, series in sample["closes"].items()},
    )
    assert load_prices(csv_path) == expected


def test_vol_series_takes_log_returns_of_the_real_closes(csv_path, sample):
    vol = risk.vol_series(csv_path, window=2)
    assert vol.returns.base_date == "2024-01-02"
    assert vol.returns.dates == tuple(sample["dates"][1:])
    closes = sample["closes"]["AAA"]
    expected = [math.log(b / a) for a, b in zip(closes, closes[1:], strict=False)]
    assert vol.returns.values["AAA"] == pytest.approx(expected)
    assert vol.annualized is True
    assert all(series[:2] == (None, None) for series in vol.values.values())
    assert all(value is not None and value > 0 for value in vol.values["BBB"][2:])


def test_risk_report_runs_the_three_pipelines_and_writes_what_it_returns(csv_path, tmp_path):
    out = tmp_path / "report.json"
    report = risk.risk_report(csv_path, out, window=2)
    vol = risk.vol_series(csv_path, window=2)
    assert [row["ticker"] for row in report.rows] == ["AAA", "BBB"]
    assert [row["last_vol"] for row in report.rows] == pytest.approx(
        [vol.values["AAA"][-1], vol.values["BBB"][-1]]
    )
    assert all(row["max_drawdown"] < 0 for row in report.rows)
    assert json.loads(out.read_text()) == {"tickers": [dict(row) for row in report.rows]}


def test_risk_report_narrows_to_requested_tickers(csv_path, tmp_path):
    report = risk.risk_report(csv_path, tmp_path / "report.json", window=2, tickers=["BBB"])
    assert [row["ticker"] for row in report.rows] == ["BBB"]


def test_risk_report_raises_key_error_for_a_ticker_missing_from_the_csv(csv_path, tmp_path):
    with pytest.raises(KeyError):
        risk.risk_report(csv_path, tmp_path / "report.json", window=2, tickers=["ZZZ"])


def test_risk_report_raises_gap_error_for_a_gap_over_five_dates(tmp_path, sample):
    days = [f"2024-02-{d:02d}" for d in range(1, 10)]
    payload = {
        "dates": days,
        "tickers": ["AAA", "BBB"],
        "closes": {"AAA": [100.0 + i for i in range(9)], "BBB": [50.0 + i for i in range(9)]},
    }
    path = write_csv(tmp_path / "gappy.csv", payload)
    kept = [
        line
        for line in path.read_text().splitlines()
        if not (line.endswith(tuple(f"BBB,{50.0 + i}" for i in range(1, 7))))
    ]
    path.write_text("\n".join(kept) + "\n")
    with pytest.raises(GapError):
        risk.risk_report(path, tmp_path / "report.json", window=2)

